create table if not exists public.telegram_users (
  telegram_id bigint primary key,
  username text,
  first_name text not null,
  last_name text,
  photo_url text,
  auth_date timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.telegram_users enable row level security;

create policy telegram_users_public_read on public.telegram_users for select using (true);

create trigger telegram_users_updated_at before update on public.telegram_users for each row execute function public.set_updated_at();
